  Activity_124834_ActivityPlot = {
    Text = "Morimens × Mist Sequence\nInvito Speciale Collaborazione\n\"Mi chiamo Mouchette, investigatrice di... Oh giusto, non sono più l'avanguardia di A.U.G.E. Lasciate che mi presenti di nuovo—sono Mouchette, solo una ragazza dolce e carina.\""
  },
  Activity_124834_ActivityTips = {
    Text = "<Title:Regole dell'evento>\nCompleta Eredità Sbiadita Cap. 1 \"Segreto orientale\" durante l'evento \"Incontro nella Nebbia\" per ottenere gratuitamente la nuova Risvegliatrice SSR Limitata \"Mouchette\"!\nDalla 2ª alla 16ª volta in cui si ottiene la stessa Risvegliatrice SSR, ciascuna verrà convertita in 1 Frammento di Risvegliatore corrispondente e 50 Sedimenti Radicali; a partire dalla 17ª volta in poi, la Risvegliatrice SSR limitata verrà convertita in 2 Frammenti di Gnosi Raffinati, 6 Frammenti di Gnosi e 250 Sedimenti Radicali."
  },
