  Activity_132333_ActivityPlot = {
    Text = "Nell'infinito desiderio dei desideri, si desta brevemente dal suo lungo Dormiveglia e rivolge uno sguardo autentico a questo mondo opaco.\nNella vita eterna, quello sguardo è così fugace"
