  Activity_141509_ActivityName = {
    Text = "Diario di Viaggio nel Reame Segreto"
  },
  Activity_141509_ActivityTips = {
    Text = "<Title:Regole dell'Evento>\n1, Dopo aver completato le missioni degli Archivi designate, i Custodi possono riscuotere le ricompense nel \"Diario di Viaggio nel Reame Segreto\".\n2, Il \"Diario di Viaggio nel Reame Segreto\" terminerà il 27 luglio alle 09:00.\n3, Dopo aver sbloccato gli \"Archivi Premium\", completando le missioni si potranno riscuotere ricompense aggiuntive.\n4, Nota: gli \"Archivi Premium\" sbloccati in questo evento sono validi solo per questo evento. I Custodi sono pregati di valutare attentamente prima di acquistare."
  },
  Activity_141509_BannerText = {
    Text = "Archivio Speciale Disponibile!"
