  Activity_15793_ActivityName = {
    Text = "Fantasma della Città Piovosa"
  },
  Activity_15793_ActivityPlot = {
    Text = "Ogni notte di pioggia è accompagnata da delusione e solitudine.\nAlcuni perdono l'amore, altri la dignità.\nE altri ancora perdono la testa."
  },
  Activity_15793_ActivityTips = {
    Text = "<Title:Condizioni di partecipazione>\nCompleta l'\"Operazione\" 2-9 (Normale) per partecipare.\n<Title:Evento d'indagine>\nDurante il periodo dell'evento, ogni giorno verrà lanciato un nuovo evento d'indagine in \"Ombre della città della pioggia\". I Custodi possono sbloccare e indagare senza consumare inventario. Dopo aver completato l'evento d'indagine, si potranno ottenere ricompense come Nucleo puro, Distintivo d'investigazione ed Esperienza del Custode.\nAl termine dell'evento, i progressi dell'indagine di \"Ombre della città della pioggia\" verranno conservati. I Custodi possono consumare D-gemme nelle Operazioni speciali per sbloccare le indagini non completate. Completare gli eventi d'indagine non conclusi durante il periodo dell'evento garantirà ricompense coerenti con quelle dell'evento.<Title:Ricompense a tempo limitato>\nDurante l'evento saranno disponibili ricompense a tempo limitato. I Custodi possono ottenere Nucleo puro, Pietra filosofale e Argento dopo aver completato \"Ombre della città della pioggia\" (modalità Normale) e gli eventi d'indagine di \"Ombre della città della pioggia\"! Le ricompense a tempo limitato sono disponibili solo durante il periodo dell'evento e non possono essere completate o riscattate dopo la fine dell'evento."
  },
