  Activity_53727_ActivityTips = {
    Text = "<Title:Introduzione all'evento>\nLe missioni del \"Giorno del ritorno a scuola\" sono suddivise in 4 gruppi, che si sbloccano il 1°, 2°, 3° e 4° giorno dell'evento.\nI Custodi possono ottenere \"Invito ritorno a scuola\" completando le missioni del \"Giorno del ritorno a scuola\".\nUsando l'\"Invito ritorno a scuola\" i Custodi possono riscattare generose ricompense nel \"Negozio ritorno a scuola.\""
  },
