  Activity_53728_ActivityTips = {
    Text = "<Title:Panoramica dell'evento>\n Durante l'evento \"Aiuto per il Cammino del Pellegrino\", i Custodi riceveranno ricompense doppie di Rosa dorata e materiali dopo aver completato \"Tempra delle Pozioni\", \"Residuo Caotico\", \"Residuo Abissale\", \"Residuo Sanguigno\", \"Residuo Cosmico\", \"Ammasso del Caos\", \"Rovine di Pohnpei\", \"Tana del Verme\" e \"Gola di Schwarzschild\". È possibile usufruire di un totale di 6 ricompense doppie al giorno.\nLe ricompense doppie non utilizzate durante la giornata verranno azzerate alle 9:00 (GMT+8) del giorno successivo. Custodi, ricordatevi di utilizzarle in tempo!"
  },
