  Activity_54375_ActivityPlot = {
    Text = "Signore e signori.\nLa dolce notte ha sollevato il suo sipario — preparate la vostra bevanda migliore.\nQuesta è una lunga storia. Concedeteci di narrarla con calma."
  },
  Activity_54375_ActivityTips = {
    Text = "<Title:Condizioni di partecipazione>\nCompleta l'\"Operazione\" 2-9 (Normale) per partecipare.\n<Title:Evento d'indagine>\nDurante il periodo dell'evento, ogni giorno verrà lanciato un nuovo evento d'indagine da \"Tributo alla rosa\". I Custodi possono sbloccare e indagare senza consumare inventario. Dopo aver completato l'evento d'indagine, si potranno ottenere ricompense come Nucleo puro, Distintivo d'investigazione ed Esperienza del Custode.\nAl termine dell'evento, i progressi dell'indagine di \"Tributo alla rosa\" verranno conservati, e i Custodi possono consumare D-gemme nelle Operazioni speciali per sbloccare le indagini non completate. Completare gli eventi d'indagine non conclusi durante il periodo dell'evento garantirà ricompense coerenti con quelle dell'evento.<Title:Ricompense a tempo limitato>\nDurante l'evento saranno disponibili ricompense a tempo limitato. I Custodi possono ottenere Nucleo puro, Pietra filosofale e Argento dopo aver completato \"Tributo alla rosa\" (modalità Normale) e gli eventi d'indagine di \"Tributo alla rosa\"! Le ricompense a tempo limitato sono disponibili solo durante il periodo dell'evento e non possono essere completate o riscattate dopo la fine dell'evento."
  },
  Activity_54402_ActivityName = {
    Text = "Paziente Dissociativo: Caos"
  },
  Activity_54402_ActivityTips = {
    Text = "<Title:Regole dell'evento>\nDurante l'evento \"Paziente Dissociativo: Caos\", i Custodi possono utilizzare le squadre preimpostate dal sistema contenenti \"24\" per affrontare i livelli designati un numero illimitato di volte.\nQuando si giocano i livelli dell'evento, non è possibile apportare modifiche al Risvegliatore nella Formazione squadra.\n<Title:Ricompense dell'evento>\nDopo aver completato con successo la sfida di un livello per la prima volta, puoi riscuotere le ricompense demo dall'interfaccia dell'evento."
  },
