  Activity_61369_ActivityName = {
    Text = "Ritmo Progressivo"
  },
  Activity_61369_ActivityPlot = {
    Text = "I Custodi possono scegliere una delle seguenti Ruote del destino limitate da Risvegliare gratuitamente!"
  },
  Activity_61369_ActivityTips = {
    Text = "<Title:Panoramica>\nNella misteriosa Pozza Nera, dove nubi di intrighi vorticano, la Ruota del destino gira incessantemente. Guidate dalla musica di Hameln, innumerevoli melodie si armonizzano nella Ruota del tuo viaggio. Possa il loro aiuto accompagnarti fino all'ultima nota della sinfonia finale.\n\n<Title:Regole dell'evento>\nDurante l'evento, accedi per un giorno per selezionare e risvegliare una delle seguenti 12 Ruote limitate, tra cui: Inno al Sovrano, Rarità Preziosa, In Nome della Rosa, Grazia Attraverso il Dolore, Nascita Celata, Editto della Regina, Tavola del Divino, Divoramento Aberrante, Potere dei devoti, L'Ultimo Verso, Nutrimento Misericordioso e Ora della Fortuna."
  },
  Activity_61369_BannerText = {
    Text = "Ottieni una Ruota del destino limitata gratuitamente"
  },
  Activity_61370_ActivityName = {
    Text = "Cuore d'Argento Puro"
  },
  Activity_61370_ActivityPlot = {
    Text = "Accedi ogni giorno per ottenere la Ruota del destino SSR commemorativa in edizione limitata \"Cuore d'Argento Puro\", fino a 16 in totale!"
  },
  Activity_61370_ActivityTips = {
    Text = "<Title:Introduzione>\nNon importa quanto il mondo possa capovolgersi, finché tutti custodiranno il proprio cuore d'argento puro e originale, la storia inevitabilmente tornerà a ripetersi, e nuova vita rinascerà sulla terra desolata.\n\n<Title:Regole dell'Evento>\nDurante l'evento, i Custodi possono accedere ogni giorno per ottenere la Ruota del destino SSR in edizione limitata \"Cuore d'Argento Puro\", per un totale di 16 riscossioni.\nLe ricompense verranno sbloccate in ordine in base agli accessi cumulativi dei Custodi, e le ricompense di accesso giornaliero si aggiorneranno alle 9:00 (GMT+8)"
  },
  Activity_61370_BannerText = {
    Text = "AdM SSR in edizione limitata gratuita"
  },
  Activity_61371_ActivityName = {
    Text = "Preghiere delle Ali Esagonali"
  },
  Activity_61371_ActivityPlot = {
    Text = "Nel tumulto della Pozza Nera, l'Argento proveniente da infinite Dimensioni si è disperso lungo le sue sponde attraverso fratture dimensionali. Tawil li ha raccolti con cura e li ha riposti in un angolo della Pozza Nera. Sebbene questo Argento non possa fermare la diffusione della Dissoluzione, i sentimenti e le emozioni che custodisce brilleranno splendidamente per sempre."
  },
  Activity_61371_ActivityTips = {
    Text = "<Title:Panoramica>\nNel tumulto della Pozza Nera, l'Argento disperso attraverso le fratture dimensionali da infinite Dimensioni giace ai bordi della Pozza Nera. Tawil li raccoglie con cura e li ripone in un angolo della Pozza Nera. Sebbene questo Argento non possa fermare la diffusione della Dissoluzione, i ricordi e i sentimenti che custodisce brilleranno sempre splendidamente.\n\n<Title:Regole dell'Evento>\nDurante l'evento, i Custodi possono accedere ogni giorno per ricevere 1000 Argento durante l'attività, per un massimo di 6 riscossioni.\nAl 7° giorno di accesso cumulativo, i Custodi potranno ottenere direttamente il Risvegliatore in edizione limitata \"Tawil\"!\nLe ricompense verranno sbloccate in sequenza in base agli accessi giornalieri cumulativi dei Custodi, e le ricompense di accesso giornaliero si aggiorneranno alle 9:00 (GMT+8)."
  },
  Activity_61371_BannerText = {
    Text = "Accedi per ottenere tantissimo Argento"
  },
