  Activity_65387_ActivityName = {
    Text = "Le Scuse del Gatto della Scuola"
  },
  Activity_65387_ActivityPlot = {
    Text = "A causa delle recenti vulnerabilità nelle misure protettive della scuola, <Del:\"Traduzione Suggerita, Punto Rosso\"> gli incidenti di Molestia da Dissoluzione nel campus sono in aumento, causando grandi disagi agli studenti. Pertanto, l'amministrazione scolastica ha allestito diversi punti di rifornimento per distribuire materiali come compensazione. (Data la responsabilità per la negligenza nella gestione delle strutture, tutti i materiali di rifornimento questa volta saranno trasportati interamente dal Gatto della Scuola.)"
  },
  Activity_65387_ActivityTips = {
    Text = "<Title:Panoramica>\nRecentemente, a causa di falle nelle misure protettive della scuola, si è verificato un numero crescente di <Del>\"testo temporaneo, punto rosso\"> incidenti di Dissoluzione che disturbano il campus, causando notevoli disagi agli studenti. Pertanto, l'amministrazione scolastica ha allestito diversi punti di rifornimento per distribuire le scorte come compensazione. (A causa della responsabilità per errori nella gestione delle strutture, la distribuzione dei materiali sarà interamente gestita dal Gatto della scuola.)\n\n<Title:Regole dell'Evento>\nDurante l'evento, i Custodi possono accedere ogni giorno per ottenere 500 Argento da \"Le Scuse del Gatto della Scuola\", per un massimo di 5 riscossioni.\nLe ricompense verranno sbloccate in sequenza in base agli accessi giornalieri cumulativi dei Custodi, e le ricompense di accesso giornaliero si aggiorneranno alle 9:00 (GMT+8)."
  },
  Activity_65387_BannerText = {
    Text = "Accedi per ottenere Argento"
  },
  Activity_65502_ActivityName = {
    Text = "Ritmo Progressivo: Duetto"
  },
  Activity_65502_ActivityPlot = {
    Text = "I Custodi possono scegliere una delle seguenti Ruote del destino limitate da Risvegliare gratuitamente!"
  },
  Activity_65502_ActivityTips = {
    Text = "<Title:Panoramica>\nNella misteriosa Pozza Nera, dove nubi di intrighi vorticano, la Ruota del destino gira incessantemente. Guidate dalla musica di Hameln, innumerevoli melodie si armonizzano nella Ruota del tuo viaggio. Possa il loro aiuto accompagnarti fino all'ultima nota della sinfonia finale.\n\n<Title:Regole dell'evento>\nDurante l'evento, accedi per un giorno per selezionare e risvegliare una delle seguenti 12 Ruote limitate, tra cui: Inno al Sovrano, Rarità Preziosa, In Nome della Rosa, Grazia Attraverso il Dolore, Nascita Celata, Editto della Regina, Tavola del Divino, Divoramento Aberrante, Potere dei devoti, L'Ultimo Verso, Nutrimento Misericordioso e Ora della Fortuna."
  },
  Activity_65502_BannerText = {
    Text = "Ottieni una Ruota del destino limitata gratuitamente"
  },
  Activity_65521_ActivityName = {
    Text = "Cassa di rifornimenti per l'Operazione"
  },
  Activity_65521_ActivityPlot = {
    Text = "Rifornimenti per l'Operazione forniti dall'Ufficio Amministrativo Mythag. Raffinati da Alistair dai relitti della Pozza Nera."
  },
