  Activity_68349_ActivityName = {
    Text = "Oltre le Stelle: Pre-ordine a Tempo Limitato"
  },
  Activity_68349_ActivityTips = {
    Text = "<Title:Oltre le Stelle: Pre-ordine a Tempo Limitato>\nQuesto evento di pre-ordine a tempo limitato include 8 pacchetti regalo. Il primo pacchetto può essere riscattato gratuitamente, mentre i pacchetti dal 2° all'8° richiedono l'acquisto di \"Oltre le Stelle: Pre-ordine a Tempo Limitato\" prima di poter essere riscattati.\nAcquistando \"Oltre le Stelle: Pre-ordine a Tempo Limitato\", riceverai immediatamente la ricompensa del 2° pacchetto regalo. I pacchetti successivi dovranno essere riscattati dopo uno specifico periodo di attesa.\nL'acquisto di \"Oltre le Stelle: Pre-ordine a Tempo Limitato\" è a tempo limitato e non potrà essere completato dopo la scadenza. Custode, tieni presente questo quando prendi la tua decisione."
  },
  Activity_68374_ActivityName = {
    Text = "Cofanetto regalo del Passaggio del Solstizio"
  },
  Activity_68374_ActivityPlot = {
    Text = "Un cofanetto regalo fornito dai Mythag per la celebrazione del Passaggio del Solstizio. Né il vento né il gelo possono distruggere la volontà dei Mythag di resistere alla Dissoluzione. Nella luce festosa del fuoco, le anime che si sostengono a vicenda proteggeranno tutti coloro che rifiutano di cedere al Fato."
  },
  Activity_68375_ActivityName = {
    Text = "Confezione regalo speciale anniversario"
  },
  Activity_68375_ActivityPlot = {
    Text = "Rimodellato dalla Tecnologia di chip d'argento, il suo Sguardo assume nuove forme per accompagnarti. In ogni momento dell'ultimo anno, è stato con te."
  },
