  Activity_96838_ActivityName = {
    Text = "Il Lato Oscuro della Tela"
  },
  Activity_96838_ActivityPlot = {
    Text = "Un cataclisma di colori, una frenesia di forme.\nUna tela quasi familiare, macchiata di pennellate di sangue,\ndove sotto la spatola le anime tremano e sussurrano dal lato oscuro della tela.\nL'arte più reale e perfetta giace celata dietro il velo della follia,\npoiché solo squarciando quella caotica facciata si può intravedere il volto crudo e interiore del mondo."
