  Activity_97853_ActivityPlot = {
    Text = "Hai mai immaginato come sarebbe la vita di tutti se il disastro non avesse mai colpito?\nIl tuo potere di salvare il mondo non ha dove essere impiegato, e ogni giorno ti affanni per una banale vita universitaria e per guadagnare una misera quantità di crediti. Il cortile non è più popolato da figure che si allenano per la battaglia; al suo posto, file di tende di tela per le attività dei club, insieme a voci di reclutamento e grida giocose. Quando suona la campanella, gli studenti affamati riempiono immediatamente la mensa...\nSe bussassi alle porte di coloro a cui tieni, che tipo di volti sorridenti vedresti?"
  },
  Activity_97853_ActivityStageEndContent = {
    Text = "L'evento \"Se Tutto Fosse Come Sempre\" è terminato. Attualmente è possibile partecipare solo all'\"Edificio del Consiglio Studentesco\"."
